S=[]
S.append(dict(slug="agenzie-immobiliari",es_slug="inmobiliarias",name="Agenzie immobiliari",fini="Agenzia immobiliare|un’agenzia immobiliare|agenzie immobiliari",
h1="Ogni richiesta senza risposta è una visita che non avverrà.",
lead="Le richieste arrivano dai portali, dal telefono, da WhatsApp e dal sito, a qualsiasi ora. Il tuo team è fuori per le visite. E il follow-up dipende da qualcuno che se ne ricordi.",
cta="Parliamo della tua agenzia",h2="Cosa porta via più tempo<br>a un’agenzia immobiliare.",
pains=[("Richieste fuori orario o durante una visita","Le richieste dai portali arrivano di notte, nel fine settimana o mentre l’agente mostra un altro immobile. Quando finalmente si risponde, l’interessato ha già scritto ad altre agenzie.","Il cliente riceve subito una risposta con le informazioni sull’immobile e le opzioni per visitarlo. L’agente riprende la conversazione con tutto il contesto.","IA applicata"),
("Contatti sparsi ovunque","Idealista, Fotocasa, il sito, l’email, il WhatsApp di ogni agente e il telefono dell’ufficio. Nessuno ha il quadro completo e alcuni contatti si perdono per strada.","Tutti i contatti, da qualsiasi canale arrivino, finiscono in un unico posto (il vostro CRM o quello che scegliamo insieme), senza copiarli a mano.","Integrazione degli strumenti"),
("Un follow-up affidato alla memoria","Richiamare dopo una visita, avvisare di un ribasso di prezzo, ricontattare chi ha detto «ci penso». Se nessuno se ne ricorda, l’opportunità si raffredda.","Ogni contatto ha il suo prossimo passo programmato: attività e promemoria automatici per l’agente e messaggi di follow-up per il cliente.","Automazione"),
("L’agenda delle visite","Coordinare orari con acquirenti, proprietari e agenti, confermare, ricordare e riprogrammare porta via buona parte della giornata.","Le visite vengono confermate e ricordate automaticamente a ciascuna parte, e le modifiche compaiono nell’agenda dell’agente senza telefonate avanti e indietro.","Automazione"),
("Proprietari che chiedono come va","«Quante visite ha avuto il mio appartamento?» Rispondere a ogni proprietario, uno per uno, è tempo tolto alla vendita.","Ogni proprietario riceve periodicamente un riepilogo di visite e richieste sul suo immobile, generato da ciò che il team già registra.","Automazione"),
("Acquisizione e documenti degli immobili","Visura catastale, attestato energetico, foto, dati del proprietario… Raccogliere tutto e scrivere la scheda richiede tempo, e manca sempre qualcosa.","Una checklist dei documenti che segnala cosa manca, e una prima bozza della scheda dell’immobile scritta con l’IA a partire dagli appunti dell’agente.","IA applicata")],
flow=[("22:14","Arriva da Idealista una richiesta su un trilocale."),("22:15","L’interessato riceve una risposta con le informazioni sull’immobile e gli orari disponibili per la visita."),("22:15","Il contatto viene registrato nel CRM e assegnato all’agente di quella zona."),("09:00","L’agente inizia la giornata con la richiesta, lo storico e il prossimo passo già pronti."),("12:30","La visita viene confermata e il sistema invia un promemoria al cliente e all’agente."),("19:00","Dopo la visita, l’agente lascia una nota vocale e il follow-up si programma da solo.")],
audit="In una settimana analizziamo come arrivano e vengono gestite le vostre richieste, come è organizzata l’agenda delle visite e dove si perde il follow-up."))

S.append(dict(slug="studi-commercialisti",es_slug="gestorias",name="Studi commercialisti e di consulenza",fini="Studio commercialista|uno studio commercialista o di consulenza|studi commercialisti e di consulenza",
h1="Meno tempo a rincorrere documenti. Più tempo per la consulenza.",
lead="Buona parte della giornata se ne va a chiedere documenti, sollecitare quelli mancanti, rispondere alle stesse domande e tenere d’occhio le scadenze. Il lavoro che crea davvero valore, la consulenza, resta per ultimo.",
cta="Parliamo del tuo studio",h2="Cosa porta via più tempo<br>a uno studio commercialista.",
pains=[("Chiedere e sollecitare documenti","Fatture del trimestre, buste paga, estratti conto… Ogni cliente li manda quando e come può, e sollecitarli uno per uno occupa buona parte di ogni trimestre.","Ogni cliente riceve la richiesta di ciò che manca e promemoria automatici finché non arriva, senza che nessuno debba rincorrerlo.","Automazione"),
("Documenti che arrivano da ogni canale","Email, WhatsApp, foto scattate col telefono, carta. Poi qualcuno deve rinominarli, classificarli e archiviarli nella pratica giusta.","I documenti arrivano in un unico punto, vengono classificati per cliente e tipo e archiviati automaticamente nella cartella giusta.","IA applicata"),
("Termini e scadenze","Dichiarazioni trimestrali, chiusure, rinnovi… Tenere tutto sotto controllo con fogli di calcolo e memoria è un rischio continuo.","Un calendario degli adempimenti per ogni cliente, con avvisi al team e al cliente con l’anticipo che decidete voi.","Automazione"),
("Sempre le stesse domande","«Cosa vi serve da me?», «Quando si presenta?», «Avete ricevuto quello che vi ho mandato?» Ogni risposta interrompe il lavoro.","Le domande frequenti ricevono subito risposta con le informazioni di ogni cliente, e ciò che richiede valutazione passa al consulente con il contesto.","IA applicata"),
("Dati digitati due volte","Quello che arriva in una fattura viene digitato nel programma di contabilità, e poi di nuovo altrove.","I dati vengono estratti dai documenti e passano al vostro gestionale senza digitarli due volte.","Integrazione degli strumenti"),
("Acquisizione di nuovi clienti","Lettera d’incarico, mandati di addebito, documenti iniziali, inserimento nei programmi… Ogni nuovo cliente è un piccolo progetto manuale.","Un processo di attivazione guidato: il cliente sa cosa deve fornire, firma ciò che serve e viene inserito nei vostri strumenti.","Automazione")],
flow=[("Giorno 1","Inizia il trimestre e ogni cliente riceve l’elenco di ciò che deve inviare."),("Giorno 3","Un cliente manda le sue fatture su WhatsApp; vengono classificate e archiviate nella sua pratica."),("Giorno 5","Chi non ha ancora inviato nulla riceve un promemoria, senza che nessuno lo scriva."),("Giorno 8","I dati delle fatture passano al programma di contabilità senza essere digitati."),("Giorno 10","Il consulente vede a colpo d’occhio quali clienti sono completi e quali no."),("Giorno 15","Pratica completa: il consulente riceve l’avviso per verificare e presentare.")],
audit="In una settimana analizziamo come ricevete e organizzate i documenti, come tenete sotto controllo le scadenze e quanto tempo se ne va in attività che si ripetono con ogni cliente."))

