flow=[("21:30","Qualcuno chiede informazioni sui corsi di pilates su Instagram."),("21:30","Riceve orari, prezzi e un link per prenotare una lezione di prova."),("Dopo la prova","Riceve la proposta per iscriversi."),("Ogni settimana","Prenota i corsi dal telefono; se disdice, il posto passa alla lista d’attesa."),("Assente","Se smette di venire per qualche settimana, il team riceve un avviso per riprendere il contatto.")],
